def build_agent(sandbox):
    # Add horizontal beams at y=7.5, 5.0, 2.5
    horizontal_beams = []
    for y in [7.5, 5.0, 2.5]:
        beam = sandbox.add_beam(x=10.0, y=y, width=10.0, height=1.0, density=1.0)
        horizontal_beams.append(beam)

    # Add vertical beams at x=5.0, 8.7, 11.3, 15.0
    vertical_beams = []
    for x in [5.0, 8.7, 11.3, 15.0]:
        beam = sandbox.add_beam(x=x, y=5.0, width=1.0, height=5.0, density=1.0)
        vertical_beams.append(beam)

    # Connect vertical beams to horizontal beams
    for vertical_beam in vertical_beams:
        for y in [7.5, 5.0, 2.5]:
            # Anchor point is (x, y) where x is the vertical beam's x position
            anchor_x = vertical_beam.position[0]
            anchor_y = y
            # Find the corresponding horizontal beam
            for hb in horizontal_beams:
                if hb.position[1] == y:
                    sandbox.add_joint(vertical_beam, hb, anchor=(anchor_x, anchor_y), type='rigid')
                    break

    return vertical_beams[0]  # Return any body for consistency

